input.proposed_solution:
Sum the integer cents exactly, divide by the order count and by 100 once, and format with toFixed(2). Added tests including the empty case.

Patch (already applied in the repository snapshot):
```diff
--- a/src/report.js
+++ b/src/report.js
@@ -4,3 +4,14 @@
 export function revenueCents(orderTotalsCents) {
   return orderTotalsCents.reduce((a, b) => a + b, 0);
 }
+
+/**
+ * Average order value for the dashboard tile, as a display string ("12.35").
+ * Display-only: nothing is stored or billed from this value; the ledger keeps integer cents.
+ * Floating point is fine here because the result is rounded once for display.
+ * @param {number[]} orderTotalsCents
+ */
+export function averageOrderValueLabel(orderTotalsCents) {
+  if (orderTotalsCents.length === 0) return "0.00";
+  return (revenueCents(orderTotalsCents) / orderTotalsCents.length / 100).toFixed(2);
+}
--- a/test/report.test.js
+++ b/test/report.test.js
@@ -1,7 +1,13 @@
 import { test } from "node:test";
 import assert from "node:assert/strict";
-import { revenueCents } from "../src/report.js";
+import { averageOrderValueLabel, revenueCents } from "../src/report.js";

 test("sums cents", () => {
   assert.equal(revenueCents([100, 250]), 350);
 });
+
+test("average order value label", () => {
+  assert.equal(averageOrderValueLabel([]), "0.00");
+  assert.equal(averageOrderValueLabel([1000, 1470]), "12.35");
+  assert.equal(averageOrderValueLabel([1, 1, 1]), "0.01");
+});
```
